import{z as d,x as B,o as l,c as A,q as E,j as r,D as t,d as n,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"蹦床与尾递归","description":"","frontmatter":{"title":"蹦床与尾递归","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/trampolining.md","filePath":"cs/trampolining.md","lastUpdated":1791063341000}'),p={name:"cs/trampolining.md"};function u(h,a,m,c,T,C){const o=B("Mermaid");return l(),A("div",null,[a[2]||(a[2]=E('<h1 id="蹦床与尾递归" tabindex="-1">蹦床与尾递归 <a class="header-anchor" href="#蹦床与尾递归" aria-label="Permalink to &quot;蹦床与尾递归&quot;">​</a></h1><div class="epigraph"><p>宿主语言不保证尾调用时，把「下一步计算」做成 thunk 返回给循环：蹦床反复调用，栈深度保持常数。</p><footer>—— 据 Steele 尾调用讨论；Baker, Cheney on the M.T.A.；对照[尾调用优化](/cs/tail-call-opt) 与 CPS 整理</footer></div><p>上一课<a href="/cs/coroutines-impl">协程</a> 用帧暂停。缺口是在<strong>无 TCO 的宿主</strong>（Java、C# 历史、JS 引擎不完全保证）实现 Scheme 式互递归：蹦床。虚表下一课。不重写 CPS 变换全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPS 后全是尾调用，若 <code>call</code> 真的建帧则爆栈。蹦床：函数返回 <code>Bounce { thunk }</code> 或 <code>Done { value }</code>，驱动循环 <code>while (bounce) thunk()</code>。缺口是<strong>驱动器</strong>，不是 yield 状态机。</p><p><span class="marginnote">术语翻译：thunk 就是「打包好但还没执行的一小步计算」——函数不直接调用下一个函数，而是把「帮我调 f(参数)」装进信封返回，由驱动循环拆信执行，栈于是不深。</span></p><p>Cheney on the MTA：用垃圾回收当栈——极端蹦床，点名。</p><h3 id="蹦床不是协程的-yield" tabindex="-1">蹦床不是协程的 yield <a class="header-anchor" href="#蹦床不是协程的-yield" aria-label="Permalink to &quot;蹦床不是协程的 yield&quot;">​</a></h3><p>yield 把控制交回调用者并保存局部；蹦床通常不把中间结果交给用户，只给驱动器。用户看来仍是一次 <code>eval</code>。</p><p><span class="marginnote">Baker 的 MTA。Steele。SML 编译到 C 的历史技巧。本课工程补丁，优先仍是真 TCO。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定：尾位置不调用而返回闭包。驱动：循环直到 <code>Done</code>。与闭包转换：thunk 即闭包。性能：间接多，可批处理若干步。</p>',12)),(l(),r(s,null,{default:t(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%B0%BE%E8%B0%83%E7%94%A8%22%5D%20--%3E%20TH%5B%22%E8%BF%94%E5%9B%9E%20thunk%22%5D%0A%20%20TH%20--%3E%20LOOP%5B%22%E8%B9%A6%E5%BA%8A%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20LOOP%20--%3E%20D%5B%22Done%20%E5%80%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 JIT：宿主若能识别驱动循环，仍难内联互递归。真 TCO 更好。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：JVM 默认栈大约撑 1 万层递归就溢出；同样的逻辑改成蹦床，跑 100 万步栈深也不变——代价是每步多一次闭包分配加一次间接调用，通常慢数倍。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"调试栈无意义。异常：要穿过驱动器。不要在 thunk 里无意非尾调用。",-1)),a[7]||(a[7]=e("p",null,"与生成器：可把蹦床当无用户可见暂停的协程驱动。",-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为写成尾递归编译器就一定会优化。JVM 与 CPython 默认都不做 TCO；不确认宿主行为就依赖它，小数据测试没事，上生产遇到长输入直接爆栈。")],-1)),(l(),r(s,null,{default:t(()=>[i(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E6%99%AE%E9%80%9A%E9%80%92%E5%BD%92%E8%B0%83%20100%20%E4%B8%87%E5%B1%82%22%5D%20--%3E%20SO%5B%22%E8%B0%83%E7%94%A8%E6%A0%88%E5%A0%86%20100%20%E4%B8%87%E5%B8%A7%3Cbr%2F%3EStackOverflow%22%5D%0A%20%20TRAMP%5B%22%E8%B9%A6%E5%BA%8A%E7%89%88%E8%B0%83%20100%20%E4%B8%87%E6%AD%A5%22%5D%20--%3E%20STEP%5B%22%E6%AF%8F%E6%AD%A5%EF%BC%9A%E5%87%BD%E6%95%B0%E8%BF%94%E5%9B%9E%E4%B8%8B%E4%B8%80%E4%B8%AA%20thunk%22%5D%0A%20%20STEP%20--%3E%20EXE%5B%22%E9%A9%B1%E5%8A%A8%E5%99%A8%E8%B0%83%E7%94%A8%20thunk%3Cbr%2F%3E%E6%A0%88%E4%B8%8A%E5%A7%8B%E7%BB%88%E5%8F%AA%E6%9C%89%E5%BE%AA%E7%8E%AF%E8%BF%99%E4%B8%80%E5%B8%A7%22%5D%0A%20%20EXE%20--%3E%20FIN%5B%22%E6%94%B6%E5%88%B0%20Done%20%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%3Cbr%2F%3E%E6%A0%88%E6%B7%B1%E4%BB%8D%E6%98%AF%E5%B8%B8%E6%95%B0%22%5D%0A%20%20SO%20-.-%3E%7C%22%E5%AF%B9%E7%85%A7%22%7C%20STEP%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写虚表。后课默认：无 TCO 时用蹦床保栈。下一课虚表与动态分派。</p><p>也不把蹦床当体操。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蹦床：返回 thunk + 循环，模拟 TCO。</li><li>性能差于真尾调用；用于宿主限制。</li><li>thunk 是闭包。</li><li>出处：Steele；Baker MTA；对照 Appel CPS。</li></ul>',5))])}const f=d(p,[["render",u]]);export{D as __pageData,f as default};
